import{f as n,J as d,o as a,c as r,k as t,a as i,b as l,w as s,K as h,a7 as c,a6 as g}from"./chunks/framework.Dd1qhYRL.js";const v=JSON.parse('{"title":"Modeling best practices","description":"How to produce an ignatius model that survives a stakeholder review and is worth handing to an agent as a specification.","frontmatter":{"title":"Modeling best practices","description":"How to produce an ignatius model that survives a stakeholder review and is worth handing to an agent as a specification."},"headers":[],"relativePath":"modeling/best-practices.md","filePath":"modeling/best-practices.md"}'),p={name:"modeling/best-practices.md"};function m(k,e,u,b,y,w){const o=d("Mermaid");return a(),r("div",null,[e[1]||(e[1]=t("h1",{id:"modeling-best-practices",tabindex:"-1"},[i("Modeling best practices "),t("a",{class:"header-anchor",href:"#modeling-best-practices","aria-label":"Permalink to “Modeling best practices”"},"​")],-1)),e[2]||(e[2]=t("p",null,"A model earns its keep when someone who does not write SQL can read it, disagree with it, and be right.",-1)),e[3]||(e[3]=t("p",null,"The model is agreed before any SQL exists, so a wrong entity boundary costs a conversation instead of a migration.",-1)),(a(),l(c,null,{default:s(()=>[h(o,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22write%20the%20model%20files%22%5D%20--%3E%20B%7B%22ignatius%20validate%22%7D%0A%20%20%20%20B%20--%3E%7C%22errors%22%7C%20A%0A%20%20%20%20B%20--%3E%7C%22clean%22%7C%20C%5B%22ignatius%20export%22%5D%0A%20%20%20%20C%20--%3E%20D%7B%22stakeholder%20review%22%7D%0A%20%20%20%20D%20--%3E%7C%22disagrees%22%7C%20A%0A%20%20%20%20D%20--%3E%7C%22signs%20off%22%7C%20E%5B%22agent%20writes%20db%2Fsql%2F%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=g(`<h2 id="what-belongs-in-the-model" tabindex="-1">What belongs in the model? <a class="header-anchor" href="#what-belongs-in-the-model" aria-label="Permalink to “What belongs in the model?”">​</a></h2><ul><li><strong>Decisions, not storage.</strong> Types are logical. Whether <code>text</code> becomes <code>varchar(255)</code>, which index it gets, and how it partitions belong in the SQL (<a href="/modeling/model-to-sql.html">From model to SQL</a>).</li><li><strong>The reason, in the body.</strong> Frontmatter is the structure. The body is the argument a stakeholder reviews. The <code>party</code> body says every table in sales and billing inherits <code>party_id</code>, which is what stops one customer&#39;s payment from settling another customer&#39;s invoice. A schema dump cannot give you that sentence.</li><li><strong>Two or three example rows per entity.</strong> Validation catches a broken reference, not a wrong rule. A row that reads wrong when you read it back exposes the rule.</li><li><strong>Stores that are not tables.</strong> Caches, log files, queues, exported spreadsheets, and signed forms hold data nobody versioned. Give each a <code>stores/&lt;name&gt;.md</code> that says what is written to it, who reads it, and how long it is kept.</li></ul><h2 id="how-do-i-choose-keys-and-name-relationships" tabindex="-1">How do I choose keys and name relationships? <a class="header-anchor" href="#how-do-i-choose-keys-and-name-relationships" aria-label="Permalink to “How do I choose keys and name relationships?”">​</a></h2><ul><li>Describe <code>pk</code>, <code>columns</code>, and <code>on</code>. Leave <code>classification</code>, <code>identifying</code>, and cardinality out: ignatius derives them (<a href="/modeling/entities.html#what-gets-derived">What gets derived</a>).</li><li>Choose inherited or surrogate keys on purpose. Inherited keys stop a child attaching to the wrong parent and put the owning party on every row. Surrogate keys suit lookup tables and roots such as <code>party</code>. Record the reason in the entity body.</li><li>When a team disagrees, serve the three variants of one model in the ignatius repository (<code>key-inherited</code>, <code>orm-hybrid</code>, <code>orm-pure</code> under <code>models/</code>). Only the keys differ.</li><li>Name each relationship with a business act: <code>is placed by</code>, not <code>belongs to</code> (<a href="/modeling/entities.html#what-goes-in-a-predicate">What goes in a predicate?</a>).</li></ul><h2 id="how-do-i-write-flows" tabindex="-1">How do I write flows? <a class="header-anchor" href="#how-do-i-write-flows" aria-label="Permalink to “How do I write flows?”">​</a></h2><ul><li><strong>Processes are verbs.</strong> <code>Place-Order</code>, <code>Issue-Invoice</code>, and <code>Collect-Payment</code> read as work. <code>Payment-Handler</code> names a component, which belongs in an architecture diagram.</li><li><strong>Flow data lists fields.</strong> Write &quot;transaction reference, status, raw response&quot;, not &quot;log data&quot;. A reviewer can only catch a missing field that was named.</li><li><strong>Decompose only where the detail changes a decision.</strong> A sub-diagram must balance with its parent, and <code>flow.unbalanced_decomposition</code> checks it at every level. Two levels that stay balanced beat four that drift.</li></ul><h2 id="review-before-you-build" tabindex="-1">Review before you build <a class="header-anchor" href="#review-before-you-build" aria-label="Permalink to “Review before you build”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.html</span></span></code></pre></div><p><code>validate</code> exits <code>1</code> on errors and <code>0</code> otherwise, so warnings alone do not fail it. Read them anyway: <code>entity.unknown_group</code> is a group file you never wrote, <code>cluster.no_discriminator</code> is an exclusive cluster that cannot tell its members apart, and <code>flow.unknown_attribute</code> is a flow promising a column the entity lacks.</p><p><code>export</code> writes one HTML file holding the graph, the dictionary, and the flows. It works offline, so attach it to the ticket or mail it. Set <code>branding</code> in <code>ignatius.yml</code> first, because the default logo, title, and copyright are the tool&#39;s own (<a href="/modeling/branding.html">Branding your model</a>). Then give the agreed model to your agent as the specification for the SQL.</p><p>When an agent edits the model, review the edit as a diff. Record the baseline before it starts:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> approve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Approved 0 change(s), cleared 0 note(s).</span></span></code></pre></div><p>Then open <code>ignatius serve model</code>. It marks every added, changed, and removed entity, column, relationship, and flow node since the last approval, and lists each beside the change note that explains it. Run <code>approve</code> again to accept the edit. The <a href="/modeling/modeling-skill.html">modeling skill</a> writes the note.</p><p>Commit the model folder in the repository whose schema it describes. The <code>.gitignore</code> ignatius writes keeps <code>.ignatius/</code> out. A schema change and its model change land in one reviewable commit, and CI can run <code>validate</code> next to your other checks.</p><h2 id="where-can-i-see-a-finished-model" tabindex="-1">Where can I see a finished model? <a class="header-anchor" href="#where-can-i-see-a-finished-model" aria-label="Permalink to “Where can I see a finished model?”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/noormdev/ignatius.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius/models/llm-memory-db-mssql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span></span></code></pre></div><p>It validates clean and mixes keys on purpose: <code>Agent</code> and <code>Artifact</code> are surrogate roots, while <code>Milestone</code>, <code>Task</code>, and <code>Task_Artifact</code> inherit <code>milestone_id</code> and <code>task_no</code> down the chain.</p><h2 id="what-bites" tabindex="-1">What bites <a class="header-anchor" href="#what-bites" aria-label="Permalink to “What bites”">​</a></h2><table tabindex="0"><thead><tr><th>Mistake or symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Review comments argue about <code>varchar</code> lengths</td><td>physical types sit in the model</td><td>keep types logical and decide them in the SQL</td></tr><tr><td>Warnings pile up unread</td><td><code>validate</code> exits <code>0</code> on warnings</td><td>read each one, because each names a real gap</td></tr><tr><td>The export carries the tool&#39;s logo and title</td><td><code>branding</code> is unset</td><td>set it before the file leaves your team</td></tr><tr><td>A reviewer cannot tell what crosses an arrow</td><td><code>data:</code> on a non-table flow says &quot;log data&quot;</td><td>list the fields</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/modeling/entities.html">Entities and key inheritance</a></li><li><a href="/modeling/data-flows.html">Data flows</a></li><li><a href="/modeling/modeling-skill.html">The modeling skill</a></li><li><a href="/modeling/branding.html">Branding your model</a></li></ul>`,22))])}const F=n(p,[["render",m]]);export{v as __pageData,F as default};
